// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;

    function setUp() public { c = new airdrop(); }

    // Fuzz the from address and a boolean that decides whether the callee should revert or succeed.
    // We must deploy a helper callee that either accepts the transferFrom call (returns true) or reverts.
    function testFuzz_property(address from, bool shouldRevert) public {
        // bound 'from' to non-zero to be a realistic caller (but keep wide)
        if (from == address(0)) from = address(1);

        // Prepare a single recipient array so loop is executed exactly once (avoids needing accumulation)
        address[] memory tos = new address[](1);

        // Deploy helper that either reverts on transferFrom or records the call and returns true
        CalleeHelper helper = new CalleeHelper(shouldRevert);
        tos[0] = address(helper);

        // Call c.transfer and observe whether it completes (does not revert).
        bool ok;
        try c.transfer(from, address(helper), tos, 123) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: Reference C requires inner call success and thus returns true (does not revert)
        // when the callee succeeds, and reverts when the callee reverts. Therefore:
        // - when shouldRevert == false, the reference will complete (ok == true)
        // - when shouldRevert == true, the reference will revert (ok == false)
        // The mutant inverts the require check and thus will do the opposite for at least one of these cases.
        // We assert the reference's expected behavior here: ok equals !shouldRevert.
        assertTrue(ok == (!shouldRevert));
    }
}

// Helper callee that either reverts on transferFrom or implements the exact selector
// transferFrom(address,address,uint256) and records that it was called.
contract CalleeHelper {
    bool public shouldRevert;
    event Called(address fromArg, address toArg, uint256 v);

    constructor(bool _shouldRevert) {
        shouldRevert = _shouldRevert;
    }

    // Match the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        if (shouldRevert) revert("callee revert");
        emit Called(from, to, v);
        return true;
    }

    // fallback to be safe
    fallback() external payable {
        if (shouldRevert) revert("callee revert fallback");
    }
    receive() external payable {}
}
